package com.tencent.weknora.knowledge;

import static org.junit.jupiter.api.Assertions.*;
import com.fasterxml.jackson.databind.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.test.web.servlet.request.MockMvcRequestBuilders;

/** Public authorization and real upload/model/physical aliases, including provider races. */
class ChunkQuestionRegenerationPipelineHttpIntegrationTest extends ChunkQuestionPipelineHttpIntegrationTest {
  Runnable chatMutation=()->{};
  void questionProvider(){s.server.createContext("/v1/chat/completions",exchange->{try{var request=json.readTree(exchange.getRequestBody());s.requests.add(request);s.chats.incrementAndGet();assertEquals(.7,request.path("temperature").asDouble());assertEquals(512,request.path("max_tokens").asInt());assertTrue(request.path("messages").get(0).path("content").asText().contains("English"));chatMutation.run();byte[] response=json.writeValueAsBytes(Map.of("choices",List.of(Map.of("message",Map.of("role","assistant","content","1. First regeneratedaliasmarker question 中文\n2. Second regeneratedaliasmarker question 中文\n3. Third regeneratedaliasmarker question 中文"),"finish_reason","stop"))));exchange.getResponseHeaders().set("Content-Type","application/json");exchange.sendResponseHeaders(200,response.length);try(var out=exchange.getResponseBody()){out.write(response);}}finally{exchange.close();}});}
  JsonNode regenerate(String chunk,String credential,boolean machine,int status)throws Exception{var response=s.f.mvc.perform(MockMvcRequestBuilders.post("/api/v1/chunks/by-id/"+chunk+"/questions/regenerate").header(machine?"X-API-Key":"Authorization",machine?credential:"Bearer "+credential).header("Accept-Language","en-US").contentType("application/json").content("invalid JSON deliberately ignored by Go")).andReturn().getResponse();assertEquals(status,response.getStatus(),response.getContentAsString());return json.readTree(response.getContentAsByteArray());}
  @Test void creatorViewerRegenerationReplacesAllPhysicalAliasesWithoutBodyRevisionOrRefresh()throws Exception{
    String doc=prepared(),chunk=chunk(doc);questionProvider();var source=retained(doc).subList(0,4);var body=s.f.jdbc.queryForList("SELECT content,content_revision,source_content,source_locators,index_status FROM chunks WHERE id=?",chunk);long jobs=s.f.jdbc.queryForObject("SELECT COUNT(*) FROM java_task_jobs",Long.class);int chats=s.chats.get(),embeddings=s.embeddings.get();
    s.f.jdbc.update("UPDATE tenant_members SET role='viewer' WHERE user_id='owner' AND tenant_id=8");String owner=s.f.token("owner",8);var previous=new HashSet<String>();
    for(int attempt=1;attempt<=2;attempt++){
      var items=regenerate(chunk,owner,false,200).path("data");assertEquals(3,items.size());var current=new HashSet<String>();for(var item:items){String id=item.path("id").asText();assertEquals(id,UUID.fromString(id).toString());assertEquals(0,item.path("content_revision").asInt());assertTrue(current.add(id));assertFalse(previous.contains(id));String alias=chunk+"-q"+HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(id.getBytes(java.nio.charset.StandardCharsets.UTF_8)),0,12);assertTrue(s.f.jdbc.queryForObject("SELECT content FROM lite_embeddings WHERE source_id=?",String.class,alias).contains(item.path("question").asText()));}
      assertEquals(4,s.f.jdbc.queryForObject("SELECT COUNT(*) FROM lite_embeddings WHERE chunk_id=?",Integer.class,chunk));assertEquals(3,s.f.jdbc.queryForObject("SELECT COUNT(*) FROM lite_embeddings_fts t JOIN lite_embeddings e ON e.id=t.rowid WHERE lite_embeddings_fts MATCH 'regeneratedaliasmarker' AND e.chunk_id=?",Integer.class,chunk));assertEquals(body,s.f.jdbc.queryForList("SELECT content,content_revision,source_content,source_locators,index_status FROM chunks WHERE id=?",chunk));assertEquals(source,retained(doc).subList(0,4));assertEquals(0,s.f.jdbc.queryForObject("SELECT COUNT(*) FROM chunk_revisions WHERE chunk_id=?",Integer.class,chunk));assertEquals(jobs,s.f.jdbc.queryForObject("SELECT COUNT(*) FROM java_task_jobs",Long.class));assertEquals(chats+attempt,s.chats.get());assertEquals(embeddings+attempt,s.embeddings.get());previous=current;
    }
  }
  @Test void sharedContributorAndApiScopeUseEffectiveOwnerBeforeProvider()throws Exception{
    String doc=prepared(),chunk=chunk(doc);questionProvider();s.f.jdbc.update("UPDATE tenant_members SET role='contributor' WHERE user_id='caller'");int chats=s.chats.get(),embeddings=s.embeddings.get();String ingest=key("ingest",false,"trace-kb"),retrieve=key("retrieve",false,"trace-kb"),wrong=key("ingest",true,"other-kb");
    regenerate(chunk,retrieve,true,403);regenerate(chunk,wrong,true,403);regenerate(chunk,s.f.foreignToken,false,403);assertEquals(chats,s.chats.get());assertEquals(embeddings,s.embeddings.get());regenerate(chunk,s.f.callerToken,false,200);regenerate(chunk,ingest,true,200);assertEquals(chats+2,s.chats.get());assertEquals(embeddings+2,s.embeddings.get());assertEquals(8,s.f.jdbc.queryForObject("SELECT tenant_id FROM chunks WHERE id=?",Long.class,chunk));
  }
  @Test void acceptedConcurrentBodyEditDuringChatCannotBeOverwrittenOrReindexed()throws Exception{
    String doc=prepared(),chunk=chunk(doc);questionProvider();int embeddings=s.embeddings.get();var old=indexes(doc);chatMutation=()->s.f.jdbc.update("UPDATE chunks SET content='Successor body evidence',content_revision=1 WHERE id=?",chunk);
    assertEquals("chunk revision conflict",regenerate(chunk,s.f.callerToken,false,400).path("error").path("message").asText());assertEquals(embeddings,s.embeddings.get());assertEquals("Successor body evidence",s.f.jdbc.queryForObject("SELECT content FROM chunks WHERE id=?",String.class,chunk));assertEquals(old,indexes(doc));assertNull(s.f.jdbc.queryForObject("SELECT metadata FROM chunks WHERE id=?",String.class,chunk));
  }
  @Test void concurrentQuestionEditDuringEmbeddingRetainsSuccessorMetadataAndRejectsStalePublication()throws Exception{
    String doc=prepared(),chunk=chunk(doc);questionProvider();String successor="{\"generated_questions\":[{\"id\":\"successor\",\"question\":\"Successor alias evidence\"}]}";
    s.server.createContext("/v1/embeddings",exchange->{try{var request=json.readTree(exchange.getRequestBody());s.requests.add(request);s.embeddings.incrementAndGet();s.f.jdbc.update("UPDATE chunks SET metadata=? WHERE id=?",successor,chunk);var data=json.createArrayNode();for(int i=0;i<request.path("input").size();i++)data.add(json.createObjectNode().put("index",i).set("embedding",json.createArrayNode().add(1).add(0).add(0)));byte[] response=json.writeValueAsBytes(json.createObjectNode().set("data",data));exchange.getResponseHeaders().set("Content-Type","application/json");exchange.sendResponseHeaders(200,response.length);try(var out=exchange.getResponseBody()){out.write(response);}}finally{exchange.close();}});
    assertEquals("chunk revision conflict",regenerate(chunk,s.f.callerToken,false,400).path("error").path("message").asText());assertEquals(json.readTree(successor),json.readTree(s.f.jdbc.queryForObject("SELECT metadata FROM chunks WHERE id=?",String.class,chunk)));assertEquals(0,s.f.jdbc.queryForObject("SELECT COUNT(*) FROM lite_embeddings WHERE chunk_id=?",Integer.class,chunk));assertEquals(0,s.f.jdbc.queryForObject("SELECT content_revision FROM chunks WHERE id=?",Integer.class,chunk));
  }
}
